    'NÜR': { ring: 'hell' },                    // rundes Abzeichen in Club-Rot = 1. FCN
    HHP: { ring: 'hell' },                      // braunes Rund = St. Pauli
    'KÖL': { ring: 'hell' },                    // rotes Rund mit „Köln“ = 1. FC Köln
