    const nameVon = t => (t.id === 'fcm' && hatClub() ? CLUB.name : t.name);
    const stand = teams.length + '|' + teams.map(nameVon).sort().join(',').length + '|' + (hatClub() ? CLUB.name : '');
    if (FIG_KARTE && FIG_STAND === stand) return FIG_KARTE;
