  const EINHEIT = '(?:\\p{Regional_Indicator}{2}|(?:\\p{Extended_Pictographic}|[✓✗✘☆])(?:\\uFE0F|\\u20E3|[\\u{1F3FB}-\\u{1F3FF}]|[\\u{E0020}-\\u{E007F}]|\\u200D\\p{Extended_Pictographic})*)';
