      if (d < 0.02) { w.weg.shift(); continue; }
      if (w.z > 5.75 && zz < w.z && L.fz.some(f => f.art !== 'bahn' && Math.abs(f.z - ZM_W) < 0.3 && Math.abs(f.x - SX) < f.L / 2 + 0.1)) continue;
