        if (tipp && A.bildpunkt && performance.now() - tipp.t < 450 && EXTRAS.some(x => { try { return typeof x.tippen === 'function' && x.tippen(tbx * BW, tby * BH); } catch (er) { return false; } })) { ziehen = null; tipp = null; return; }
