    r.classList.toggle('ts-wb', !!k);
    const kopf = r.querySelector('.ts-kopf'), alt = kopf && kopf.querySelector('.ts-wb-marke');
    if (alt && (!k || alt.dataset.k !== k)) alt.remove();
